// ---- Shared helpers: injected into every Code node by scripts/build-workflow.js ----

const ANTHROPIC_VERSION = '2026-10-21';

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// Replace {{name}} with vars.name; unknown placeholders are left as-is.
function fill(template, vars) {
  return template.replace(/\{\{(\w+)\}\}/g, (m, k) => (k in vars ? String(vars[k] ?? '') : m));
}

// One LLM call for the configured provider: { request, request_url, request_headers }.
//   provider 'openai': any OpenAI-compatible chat endpoint (Gemini, Groq, OpenRouter, Ollama).
//   provider 'claude': Claude Messages API. Version 2026-10-21 rejects temperature/top_p/top_k,
//                      so depth and cost are controlled with output_config.effort instead.
function aiCall(cfg, tier, prompt, vars, { maxTokens, effort, temperature }) {
  const llm = cfg.llm;
  const content = fill(prompt.user, vars);

  if (llm.provider === 'claude') {
    const request = {
      model: llm.models[tier],
      max_tokens: maxTokens,
      output_config: { effort },
      messages: [{ role: 'user', content }],
    };
    const request_headers = { 'anthropic-version': ANTHROPIC_VERSION };
    if (prompt.system) request.system = prompt.system;
    if (tier === 'fast') {
      request.thinking = { type: 'disabled' };
    } else {
      request.fallbacks = 'default'; // server-side refusal fallback
      request_headers['anthropic-beta'] = 'server-side-fallback-2026-07-01';
    }
    return { request, request_url: 'https://api.anthropic.com/v1/messages', request_headers };
  }

  const messages = [];
  if (prompt.system) messages.push({ role: 'system', content: prompt.system });
  messages.push({ role: 'user', content });
  return {
    request: { model: llm.models[tier], messages, max_tokens: maxTokens, temperature },
    request_url: llm.url,
    request_headers: {},
  };
}

// Text of an LLM response (Claude or OpenAI-compatible); '' for failed calls
// (Continue On Fail) and refusals.
function responseText(res) {
  if (!res || res.error) return '';
  if (Array.isArray(res.choices)) {
    const msg = res.choices[0] && res.choices[0].message;
    return msg && typeof msg.content === 'string' ? msg.content.trim() : '';
  }
  if (res.stop_reason === 'refusal') return '';
  return (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
}

// True when the model stopped because it hit max_tokens.
function isTruncated(res) {
  if (!res) return false;
  if (Array.isArray(res.choices)) return !!res.choices[0] && res.choices[0].finish_reason === 'length';
  return res.stop_reason === 'max_tokens';
}

function parseJson(raw, label) {
  const clean = String(raw || '').replace(/```json|```/g, '').trim();
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  try {
    return JSON.parse(start >= 0 && end > start ? clean.slice(start, end + 1) : clean);
  } catch (e) {
    throw new Error(`${label}: AI returned invalid JSON: ${clean.slice(0, 300)}`);
  }
}

// Canonical form for deduping: no protocol, www, hash, tracking params or trailing slash.
function normalizeUrl(u) {
  try {
    const url = new URL(String(u).trim());
    url.hash = '';
    for (const k of [...url.searchParams.keys()]) {
      if (/^(utm_|fbclid|gclid|ref$|ref_src)/i.test(k)) url.searchParams.delete(k);
    }
    const host = url.hostname.toLowerCase().replace(/^www\./, '');
    return (host + url.pathname.replace(/\/+$/, '') + (url.search || '')).toLowerCase();
  } catch (e) {
    return String(u || '').trim().toLowerCase();
  }
}

function numberedList(arr) {
  return (arr || []).map((q, i) => `${i + 1}. ${q}`).join('\n');
}

function today() {
  return new Date().toISOString().slice(0, 10);
}
// ---- end helpers ----

// E03 Build Failure Context: recover the run's form data from the failed execution
// and prepare Prompt 09 (Failure Email).
const PROMPT = {"system":null,"user":"Write a short, apologetic failure email for an automated research request that failed.\n\nDetails:\n- Topic: {{topic}}\n- Failed stage: {{failed_stage}}\n- Plain-language reason (no technical jargon): {{friendly_reason}}\n\nRequirements:\n- Apologize briefly and say the research could not be completed.\n- Suggest what the user can try (for example: a more specific topic, fewer sources, or trying again in a few minutes).\n- Do not include stack traces, API names, or internal error details.\n- Under 80 words, kind and calm.\n- Output JSON: {\"subject\": \"string\", \"body_html\": \"string\"}"};

// ---- Keep in sync with CONFIG in 02 Validate ----
const CONFIG = {
  llm: {
    provider: 'openai',
    url: 'https://generativelanguage.googleapis.com/v1beta/openai/chat/completions',
    models: { fast: 'gemini-flash-lite-latest', strong: 'gemini-flash-latest' },
  },
  sheet_id: 'PASTE_YOUR_GOOGLE_SHEET_ID',
  sheet_tab: 'runs',
};

const err = $('E01 Error Trigger').first().json;
const exec = $input.first().json; // n8n API execution (empty or error if the lookup failed)
const runData = (exec && exec.data && exec.data.resultData && exec.data.resultData.runData) || {};
const firstJson = name => {
  try { return runData[name][0].data.main[0][0].json || {}; } catch (e) { return {}; }
};
const run = firstJson('02 Validate');
const form = firstJson('01 Form');

const failedNode = (err.execution && err.execution.lastNodeExecuted) || (err.trigger && err.trigger.node && err.trigger.node.name) || 'unknown';
const message = (err.execution && err.execution.error && err.execution.error.message) || (err.trigger && err.trigger.error && err.trigger.error.message) || 'Unknown error';

const STAGES = {
  '01': ['Intake', 'the request could not be read'],
  '02': ['Intake', 'some of the form details were missing or invalid'],
  '03': ['Planning', 'the research plan could not be created'],
  '04': ['Search', 'the web search did not return usable results'],
  '05': ['Source scoring', 'the sources could not be evaluated'],
  '06': ['Analysis', 'too few sources could be read and analyzed'],
  '07': ['Writing', 'the report could not be written'],
  '08': ['Fact-checking', 'the report could not be checked'],
  '09': ['Delivery', 'the finished report could not be prepared or sent'],
  '10': ['Fallback email', 'the follow-up email could not be sent'],
};
const [failed_stage, friendly_reason] = STAGES[failedNode.slice(0, 2)] || ['Processing', 'an unexpected problem occurred'];

const topic = run.topic || form.Topic || '(unknown topic)';
const email = run.email || String(form.Email || '').trim().toLowerCase();

return [{
  json: {
    run_id: run.run_id || `exec_${(err.execution && err.execution.id) || Date.now()}`,
    started_at: run.started_at || '',
    topic,
    email,
    has_email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email),
    depth: run.depth || '',
    style: run.style || '',
    num_sources: run.num_sources || '',
    failed_node: failedNode,
    failed_stage,
    error_message: `${failedNode}: ${message}`.slice(0, 500),
    config: CONFIG,
    ...aiCall(CONFIG, 'fast', PROMPT, { topic, failed_stage, friendly_reason }, { maxTokens: 2000, effort: 'low', temperature: 0.4 }),
  },
}];

